(window.APUSH_TOPICS=window.APUSH_TOPICS||{})[9]=[{"id": "p9-001", "period": 9, "topic_en": "Barry Goldwater and The Conscience of a Conservative", "topic_zh": "巴里·戈德华特与《一个保守派的良知》", "year": 1964, "year_text": "1964 (book published 1960)", "who": ["Barry Goldwater", "Phyllis Schlafly"], "who_zh": ["巴里·戈德华特", "菲利斯·施拉夫利"], "what_en": "Arizona senator Barry Goldwater's 1960 book The Conscience of a Conservative set forth an uncompromising conservatism attacking the New Deal state; in 1964 grassroots conservatives built a bottom-up campaign that won him the Republican presidential nomination.", "what_zh": "亚利桑那州参议员巴里·戈德华特1960年出版《一个保守派的良知》，提出毫不妥协的保守主义、攻击新政国家；1964年草根保守派自下而上为他赢得共和党总统候选人提名。", "cause_en": "Postwar Republicans favored moderates like Eisenhower, Dewey, and Rockefeller; conservatives believed the party had accommodated liberalism and hoped to remake it, mobilizing through groups like Young Americans for Freedom and Goldwater's widely distributed book.", "cause_zh": "战后共和党偏好艾森豪威尔、杜威、洛克菲勒等温和派；保守派认为共和党向自由主义妥协，决心重塑该党，通过《青年美国人自由联盟》等组织和广泛散发的戈德华特著作动员起来。", "sig_en": "Although Lyndon Johnson crushed Goldwater in a historic 1964 landslide, the nearly four million Goldwater volunteers swung their support to Ronald Reagan, laying the political groundwork for the New Right's rise a decade and a half later.", "sig_zh": "尽管林登·约翰逊在1964年以压倒性优势击败戈德华特，近四百万戈德华特志愿者转而支持里根，为十五年后新右翼的崛起奠定了政治基础。", "exp_en": "Goldwater's 1964 campaign lost the election but built the grassroots conservative movement: its volunteers, donor lists, and computerized direct-mail networks became the foundation of Reagan's later victories.", "exp_zh": "戈德华特1964年竞选输掉了大选，却建起了草根保守派运动：其志愿者、捐款人名单和电脑直邮网络成为里根日后胜利的基础。", "page": 974, "img": {"file": "img:f2_1777", "credit": "图源：Henretta《America's History》第8版 p.974"}}, {"id": "p9-002", "period": 9, "topic_en": "William F. Buckley, National Review, and free-market conservatism", "topic_zh": "威廉·F·巴克利、《国民评论》与自由市场保守主义", "year": null, "year_text": "1950s–1960s", "who": ["William F. Buckley", "Milton Friedman"], "who_zh": ["威廉·F·巴克利", "米尔顿·弗里德曼"], "what_en": "Since the 1950s, William F. Buckley used his conservative magazine National Review to attack liberal policy, while Nobel-winning Chicago economist Milton Friedman's Capitalism and Freedom (1962) argued that economic freedom was an indispensable means toward political freedom.", "what_zh": "自1950年代起，威廉·F·巴克利用其保守派杂志《国民评论》批判自由主义政策；诺贝尔奖得主、芝加哥大学经济学家米尔顿·弗里德曼在《资本主义与自由》（1962）中论证经济自由是实现政治自由不可或缺的手段。", "cause_en": "Conservatives sought an intellectual foundation against New Deal–Great Society liberalism; wealthy conservatives funded think tanks such as the Heritage Foundation, the American Enterprise Institute, and the Cato Institute to spread market-based policy ideas.", "cause_zh": "保守派寻求对抗新政—大社会自由主义的思想基础；富裕保守派资助传统基金会、美国企业研究所、卡托研究所等智库传播市场导向的政策思想。", "sig_en": "Buckley and Friedman gave the New Right its intellectual framework — relentless opposition to the growth of government and faith in free markets — which became central to Reagan's agenda.", "sig_zh": "巴克利和弗里德曼为新右翼提供了思想框架——不懈反对政府扩张、信仰自由市场，成为里根施政纲领的核心。", "exp_en": "The New Right was not only a voting coalition but an ideas movement: conservative intellectuals supplied the arguments that turned free-market economics from academic theory into governing policy.", "exp_zh": "新右翼不仅是选民联盟，更是思想运动：保守派知识分子提供的论证把自由市场经济学从学术理论变成了执政政策。", "page": 976, "img": {"file": "img:f2_1783", "credit": "图源：Henretta《America's History》第8版 p.976"}}, {"id": "p9-003", "period": 9, "topic_en": "The Religious Right and the Moral Majority", "topic_zh": "宗教右翼与道德多数派", "year": 1979, "year_text": "1979 (Moral Majority founded)", "who": ["Jerry Falwell", "Pat Robertson", "Phyllis Schlafly"], "who_zh": ["杰里·福尔韦尔", "帕特·罗伯逊", "菲利斯·施拉夫利"], "what_en": "Televangelist Jerry Falwell founded the Moral Majority in 1979, turning evangelical Christians into a political movement that condemned divorce, abortion, premarital sex, and feminism and promoted family values.", "what_zh": "电视布道家杰里·福尔韦尔1979年创立道德多数派，把福音派基督徒变成政治运动，谴责离婚、堕胎、婚前性行为和女权主义，宣扬家庭价值观。", "cause_en": "Fundamentalist Protestants had long treated politics as secondary, but the perception that American society had become immoral — legalized abortion and pornography, school busing, curtailed public expressions of religion — plus a new generation of popular ministers made politics relevant.", "cause_zh": "基要派新教徒长期把政治视为次要事务，但美国社会被认为日益堕落——堕胎与色情合法化、校车强制融合、公共场合宗教表达受限——加上一代新的大众布道家，使政治变得与他们相关。", "sig_en": "The Religious Right became one leg of the New Right's three-legged stool and a major force in Republican politics: Falwell's organization claimed two million new registered voters for 1980, and the party platform called for an abortion ban, school prayer, and opposition to the Equal Rights Amendment.", "sig_zh": "宗教右翼成为新右翼“三条腿凳子”的一条腿和共和党政治中的重要力量：福尔韦尔的组织声称为1980年大选登记了两百万新选民，共和党纲领要求禁止堕胎、恢复校园祷告、反对《平等权利修正案》。", "why_term": "family values", "why_term_q": "宗教右翼自1970年代起倡导的核心社会理念（关键词）是 ______。", "exp_en": "The Religious Right fused evangelical faith with electoral politics, giving the Republican Party a mass grassroots base motivated by moral issues rather than economics alone.", "exp_zh": "宗教右翼把福音派信仰与选举政治结合，给共和党带来一个由道德议题而非仅经济议题驱动的庞大草根基础。", "page": 976, "src": {"text": "I want you to know that this administration is motivated by a political philosophy that sees the greatness of America in you, her people, and in your families, churches, neighborhoods, communities — the institutions that foster and nourish values like concern for others and respect for the rule of law under God.", "attr": "President Ronald Reagan, remarks to the National Association of American Evangelicals, 1983"}, "img": {"file": "img:f2_1783", "credit": "图源：Henretta《America's History》第8版 p.976"}}, {"id": "p9-004", "period": 9, "topic_en": "The Iran hostage crisis", "topic_zh": "伊朗人质危机", "year": 1979, "year_text": "November 1979–January 1981", "who": ["Jimmy Carter", "Ayatollah Khomeini"], "who_zh": ["吉米·卡特", "阿亚图拉·霍梅尼"], "what_en": "Iranian militants seized the U.S. embassy in Tehran in November 1979 and held American diplomats hostage for 444 days; the hostages were finally released the day after Carter left office in January 1981.", "what_zh": "1979年11月伊朗激进分子占领美国驻德黑兰大使馆，扣押美国外交人员长达444天；人质直到卡特离任次日（1981年1月）才获释。", "cause_en": "The United States had long backed Iran's shah as a bulwark against Soviet expansion and a source of oil; after the 1979 Iranian Revolution, militants seized the embassy, and a U.S. military rescue attempt in April 1980 had to be aborted because of equipment failures in the desert.", "cause_zh": "美国长期支持伊朗国王作为遏制苏联扩张的堡垒和石油来源；1979年伊朗革命后激进分子占领大使馆，1980年4月美军营救行动因沙漠中设备故障而被迫中止。", "sig_en": "Nightly images of blindfolded, handcuffed hostages created a foreign policy crisis that destroyed Carter's reelection chances and gave Reagan a powerful issue in the 1980 campaign.", "sig_zh": "每晚电视上蒙眼戴手铐的人质画面造成外交政策危机，断送了卡特连任的机会，也给了里根1980年竞选中的有力议题。", "exp_en": "The hostage crisis symbolized American impotence abroad: a well-intentioned president was humiliated by events he could not control, and voters punished him for it.", "exp_zh": "人质危机象征美国在海外的无力：一位好心的总统被他无法控制的事件羞辱，选民为此惩罚了他。", "page": 977}, {"id": "p9-005", "period": 9, "topic_en": "The election of 1980", "topic_zh": "1980年总统大选", "year": 1980, "year_text": "November 1980", "who": ["Ronald Reagan", "Jimmy Carter"], "who_zh": ["罗纳德·里根", "吉米·卡特"], "what_en": "Ronald Reagan defeated incumbent Jimmy Carter with 50.7 percent of the popular vote; Republicans also elected thirty-three new House members and twelve new senators, taking Senate control for the first time since 1954.", "what_zh": "罗纳德·里根以50.7%的普选票击败现任总统吉米·卡特；共和党还赢得33个众议院席位和12个参议院席位，自1954年以来首次掌控参议院。", "cause_en": "Stagflation — stagnant wages, high inflation, crippling mortgage rates, nearly 8 percent unemployment — plus the hostage crisis and perceived weakness toward Soviet expansion left only 21 percent of Americans calling Carter an effective president, making him the perfect foil for Reagan's optimism.", "cause_zh": "滞胀——工资停滞、高通胀、沉重房贷利率、近8%的失业率——加上人质危机和对苏联扩张的软弱形象，使仅21%的美国人认为卡特是有效总统，他成为里根乐观主义的完美陪衬。", "sig_en": "The election signaled a new political alignment: the New Right's long road to national power culminated in victory, inaugurating a conservative era built on free markets, low taxes, and individual success.", "sig_zh": "这次大选标志着新的政治重组：新右翼通往全国权力的漫长道路以胜利告终，开启了以自由市场、低税和个人成功为核心的保守主义时代。", "exp_en": "In the televised debate Reagan asked struggling Americans, 'Are you better off today than you were four years ago?' — a question that distilled the election into a referendum on liberal governance.", "exp_zh": "在电视辩论中里根问挣扎中的美国人：“你们今天比四年前过得好吗？”——这个问题把大选浓缩为对自由派执政的全民公投。", "page": 980, "img": {"file": "img:f2_1790", "credit": "图源：Henretta《America's History》第8版 p.980"}}, {"id": "p9-006", "period": 9, "topic_en": "The Reagan coalition and Reagan Democrats", "topic_zh": "里根联盟与里根民主党人", "year": 1980, "year_text": "1980s", "who": ["Ronald Reagan"], "who_zh": ["罗纳德·里根"], "what_en": "Reagan united affluent white Protestants, Sunbelt suburbanites, southern whites drawn by the southern strategy, and blue-collar Reagan Democrats from industrial Midwestern states into a durable Republican majority.", "what_zh": "里根把富裕白人新教徒、阳光地带郊区居民、被“南方战略”吸引的南方白人，以及中西部工业州的蓝领“里根民主党人”团结成持久的共和党多数。", "cause_en": "Since 1964 southern whites had drifted from the Democrats over civil rights, and blue-collar Catholics were alienated by antiwar protesters, rising welfare spending, and feminist demands; Reagan's states'-rights speech in Philadelphia, Mississippi validated twenty-five years of southern opposition to federal civil rights legislation.", "cause_zh": "自1964年起南方白人因民权问题逐渐脱离民主党，蓝领天主教徒则被反战抗议者、不断增长的福利开支和女权主义诉求疏远；里根在密西西比州费城发表的州权演说肯定了南方二十五年来反对联邦民权立法的立场。", "sig_en": "The coalition realigned the electorate: after 1980 southern whites remained a cornerstone of the Republican Party, and the New Right commanded wider popular support than at any time since the 1920s.", "sig_zh": "这一联盟重组了选民结构：1980年后南方白人一直是共和党的基石，新右翼获得自1920年代以来最广泛的民众支持。", "why_term": "three-legged stool", "why_term_q": "新右翼的三个支柱（反共、自由市场、宗教传统）被形容为 ______。", "exp_en": "The Reagan coalition shows how cultural and racial appeals could reassemble the New Deal electoral map: economics mattered, but civil rights backlash and moral traditionalism held the new majority together.", "exp_zh": "里根联盟显示文化与种族诉求如何重组新政选举版图：经济很重要，但民权反弹和道德传统主义才是维系新多数的黏合剂。", "page": 981, "img": {"file": "img:f2_1792", "credit": "图源：Henretta《America's History》第8版 p.981"}}, {"id": "p9-007", "period": 9, "topic_en": "Supply-side economics (Reaganomics) and the Economic Recovery Tax Act", "topic_zh": "供给学派经济学（里根经济学）与《经济复兴税法》", "year": 1981, "year_text": "1981 (ERTA)", "who": ["Ronald Reagan", "David Stockman", "Jack Kemp"], "who_zh": ["罗纳德·里根", "戴维·斯托克曼", "杰克·肯普"], "what_en": "Supply-side theory held that cutting taxes on corporations and the wealthy would spur investment and production; the 1981 Economic Recovery Tax Act cut income tax rates 23 percent over three years, dropped the top marginal rate from 70 to 50 percent, and cut business taxes by $150 billion over five years.", "what_zh": "供给学派理论认为削减企业和富人税收能刺激投资与生产；1981年《经济复兴税法》在三年内削减所得税率23%，最高边际税率从70%降至50%，五年内削减企业税1500亿美元。", "cause_en": "Reagan blamed government — high taxes and regulation — for stagflation and believed 'someone can always get rich' in America; budget director David Stockman hoped matching spending cuts would balance the budget, but Congress refused to cut Social Security and Medicare.", "cause_zh": "里根把滞胀归咎于政府——高税收和管制，坚信在美国“人人总能致富”；预算主任戴维·斯托克曼希望以相应支出削减平衡预算，但国会拒绝削减社会保障和医疗保险。", "sig_en": "ERTA cut federal revenue by $200 billion a year by 1986; Stockman later admitted the optimistic projections were manipulated and rested on the discredited trickle-down notion, while budget deficits exploded.", "sig_zh": "到1986年ERTA使联邦年收入减少2000亿美元；斯托克曼后来承认乐观预测是操纵出来的、建立在已被证伪的涓滴理论上，而预算赤字则急剧膨胀。", "why_term": "trickle-down", "why_term_q": "批评者用 ______ 一词形容供给学派“帮助富人最终惠及下层”的理论。", "exp_en": "Reaganomics gambled that tax cuts would pay for themselves through growth; instead revenues fell and deficits soared, because the promised spending cuts in entitlements never materialized.", "exp_zh": "里根经济学赌的是减税能通过增长自我买单；结果收入下降、赤字飙升，因为承诺的福利支出削减从未兑现。", "page": 983}, {"id": "p9-008", "period": 9, "topic_en": "The federal budget deficit and the national debt under Reagan", "topic_zh": "里根时期的联邦预算赤字与国债", "year": null, "year_text": "1981–1989", "who": ["Ronald Reagan", "Caspar Weinberger"], "who_zh": ["罗纳德·里根", "卡斯帕·温伯格"], "what_en": "Reagan's tax cuts combined with a five-year, $1.2 trillion military buildup made the national debt triple during his presidency, even though federal spending stayed at 22.1 percent of GDP and federal taxes at 19 percent — virtually the same as in 1981.", "what_zh": "里根的减税加上五年1.2万亿美元的军事扩张，使国债在其任内翻了三倍，尽管联邦支出仍占GDP的22.1%、联邦税收占19%——与1981年几乎相同。", "cause_en": "Reagan declared, 'Defense is not a budget item. You spend what you need'; military spending took one-fourth of all federal expenditures while tax revenues fell, and Congress would not cut the two biggest budget items, Social Security and Medicare.", "cause_zh": "里根宣称“国防不是预算项目，需要多少花多少”；军费占联邦支出四分之一而税收下降，国会又不愿削减最大的两个预算项目——社会保障和医疗保险。", "sig_en": "The deficits transferred costs to future generations and contradicted Reagan's small-government rhetoric — 'There was no Reagan Revolution,' one conservative noted — yet entitlements survived and government employment actually grew.", "sig_zh": "赤字把成本转嫁给后代，也与里根小政府言论相矛盾——一位保守派评论“根本不存在里根革命”——而福利项目安然无恙，政府雇员反而增加。", "exp_en": "Reagan proved that cutting taxes while raising defense spending produces debt, not smaller government: the welfare state endured because voters, in George Will's phrase, wanted to conserve the New Deal.", "exp_zh": "里根证明了减税加扩军带来的是债务而非小政府：福利国家延续下来，因为用乔治·威尔的话说，选民想保守的是新政。", "page": 983}, {"id": "p9-009", "period": 9, "topic_en": "Deregulation under Reagan", "topic_zh": "里根时期的放松管制", "year": 1981, "year_text": "1981", "who": ["James Watt", "Anne Gorsuch Burford"], "who_zh": ["詹姆斯·瓦特", "安妮·戈萨奇·伯福德"], "what_en": "In 1981 the Reagan administration cut federal regulatory agencies' budgets by an average of 12 percent and staffed them with leaders hostile to their missions, such as Interior Secretary James Watt, who called environmentalism 'a left-wing cult' and opened public lands to oil, coal, ranching, and timber interests.", "what_zh": "1981年里根政府平均削减联邦监管机构预算12%，并任命反对机构使命的领导人，如称环保主义为“左翼邪教”的内政部长詹姆斯·瓦特，把公共土地开放给石油、煤炭、牧场和木材企业。", "cause_en": "Reagan's three-pronged assault on the liberal state targeted federal taxes, social-welfare spending, and the regulatory bureaucracy, reflecting the New Right's faith that free markets, not government rules, should guide the economy.", "cause_zh": "里根对自由派国家的三管齐下——联邦税收、社会福利支出和监管官僚机构——反映了新右翼的信念：应由自由市场而非政府规则引导经济。", "sig_en": "EPA chief Anne Gorsuch Burford refused to cooperate on toxic-waste cleanup, provoking public outrage; by his second term Reagan reversed course, raising the EPA budget and adding wilderness acreage and endangered species — proof that politics remained 'the art of the possible.'", "sig_zh": "环保署长安妮·戈萨奇·伯福德拒绝配合有毒废物清理，激起公愤；第二任期内里根掉头，提高了环保署预算，增加了荒野保护区面积和濒危物种名录——证明政治仍是“可能的艺术”。", "exp_en": "Deregulation by hostile appointment was a shortcut around Congress: rather than repeal environmental laws, Reagan installed leaders who would not enforce them.", "exp_zh": "任命反对者主导的放松管制是绕过国会的捷径：里根不废除环保法律，而是安插不愿执法的领导人。", "page": 984}, {"id": "p9-010", "period": 9, "topic_en": "Sandra Day O'Connor and Reagan's remaking of the judiciary", "topic_zh": "桑德拉·戴·奥康纳与里根重塑司法", "year": 1981, "year_text": "1981 (O'Connor appointed)", "who": ["Sandra Day O'Connor", "Antonin Scalia", "Anthony Kennedy", "William Rehnquist"], "who_zh": ["桑德拉·戴·奥康纳", "安东宁·斯卡利亚", "安东尼·肯尼迪", "威廉·伦奎斯特"], "what_en": "Reagan appointed 368 federal judges and three Supreme Court justices, including Sandra Day O'Connor in 1981 — the first woman on the Court — and elevated conservative William Rehnquist to chief justice in 1986.", "what_zh": "里根任命了368名联邦法官和三位最高法院大法官，包括1981年的桑德拉·戴·奥康纳——最高法院首位女性大法官——并于1986年擢升保守派威廉·伦奎斯特为首席大法官。", "cause_en": "Reagan and Attorney General Edwin Meese aimed to reverse the liberal judicial philosophy dominant since the late 1950s by filling the courts with conservative-credentialed judges.", "cause_zh": "里根和司法部长埃德温·米斯意图通过任命有保守派资历的法官，扭转自1950年代末以来占主导的自由派司法哲学。", "sig_en": "Ironically, O'Connor and Anthony Kennedy became moderates — O'Connor the Court's swing vote, as in Webster (1989) where she refused to overturn Roe — leaving Scalia as Reagan's only genuinely conservative appointee; the Court scaled back but rarely overturned Warren and Burger Court liberal rulings.", "sig_zh": "颇具讽刺意味的是，奥康纳和安东尼·肯尼迪成了温和派——奥康纳是法院的摇摆票，如在韦伯斯特案（1989）中拒绝推翻罗伊案——只剩斯卡利亚是里根真正保守的任命；最高法院收缩但很少推翻沃伦和伯格法院的自由派判决。", "exp_en": "Judicial appointments outlast presidencies: Reagan's courts shaped abortion, busing, and property-rights law for decades, even when his own appointees drifted from New Right orthodoxy.", "exp_zh": "司法任命比总统任期更长久：里根的法院几十年间塑造了堕胎、校车和产权法，即使他自己的任命对象偏离了新右翼正统。", "page": 984}, {"id": "p9-011", "period": 9, "topic_en": "The election of 1984 and 'Morning in America'", "topic_zh": "1984年大选与“美利坚之晨”", "year": 1984, "year_text": "November 1984", "who": ["Ronald Reagan", "Walter Mondale", "Geraldine Ferraro"], "who_zh": ["罗纳德·里根", "沃尔特·蒙代尔", "杰拉尔丁·费拉罗"], "what_en": "Campaigning on the slogan 'It's Morning in America' amid recovery from the 1981–1982 recession, Reagan won a landslide, losing only Minnesota and the District of Columbia; Mondale's running mate Geraldine Ferraro was the first woman on a major party's presidential ticket.", "what_zh": "在1981–1982年衰退后经济复苏之际，里根以“美利坚之晨”为竞选口号赢得压倒性胜利，仅输掉明尼苏达州和哥伦比亚特区；蒙代尔的竞选搭档杰拉尔丁·费拉罗是主要政党总统候选人名单上的首位女性。", "cause_en": "High Federal Reserve interest rates — as high as 18 percent — had tamed Carter-era inflation but caused a recession with nearly 10 percent unemployment and 10 million out of work; by 1983 recovery restored Reagan's approval just in time, and he even accepted a 1982 tax increase.", "cause_zh": "美联储高达18%的高利率驯服了卡特时代的通胀，却造成近10%失业率、一千万人失业的衰退；1983年经济复苏恰好在大选前恢复了里根的支持率，他甚至接受了1982年加税。", "sig_en": "The victory confirmed the conservative era's cultural hold — backward-looking nostalgia plus aggressive capitalism — though Democrats kept the House and regained the Senate in 1986.", "sig_zh": "这次胜利确认了保守主义时代的文化主导地位——怀旧情绪加激进资本主义——尽管民主党保住了众议院并在1986年夺回参议院。", "exp_en": "'Morning in America' sold optimism as policy: Reagan's mythology of small towns and neighbor helping neighbor mattered more to voters than the urban, unequal reality.", "exp_zh": "“美利坚之晨”把乐观当政策来卖：里根神话中的小镇和邻里互助，比城市化、不平等的现实更打动选民。", "page": 986, "img": {"file": "img:f2_1807", "credit": "图源：Henretta《America's History》第8版 p.986"}}, {"id": "p9-012", "period": 9, "topic_en": "The HIV/AIDS epidemic", "topic_zh": "艾滋病疫情", "year": 1981, "year_text": "1981 (virus identified)", "who": ["C. Everett Koop"], "who_zh": ["C·埃弗里特·库普"], "what_en": "In 1981 American physicians identified HIV, the virus causing AIDS; the disease killed nearly 100,000 Americans in the 1980s — more than the Korean and Vietnam Wars combined — yet the Reagan administration took little action between 1981 and 1986.", "what_zh": "1981年美国医生确认了导致艾滋病的HIV病毒；该病在1980年代夺去近十万美国人生命——超过朝鲜战争和越南战争死亡人数之和——但里根政府在1981至1986年间几乎无所作为。", "cause_en": "Because the earliest prominent victims were gay men, Reagan — emboldened by New Right conservatives, some of whose advisors called it 'God's punishment of homosexuals' — hesitated to declare a national health emergency and blocked Surgeon General C. Everett Koop from speaking forthrightly to the nation.", "cause_zh": "由于最早的显著受害者是男同性恋，里根在新右翼保守派鼓动下犹豫是否宣布全国卫生紧急状态，一些顾问甚至称这是“上帝对同性恋者的惩罚”，还阻止卫生总监库普坦率地向全国说明疫情。", "sig_en": "Pressed by gay activists and health officials, the administration finally funded treatment and vaccine research in Reagan's last years — but the delay proved costly, inhumane, and embarrassing, as the virus spread worldwide to over 50 million infected.", "sig_zh": "在同性恋活动家和卫生官员施压下，政府在里根任期最后几年终于资助治疗和疫苗研究——但拖延已造成惨重、不人道且令人难堪的后果，病毒在全球感染超五千万人。", "exp_en": "The AIDS crisis exposed the moral blind spot of 1980s conservatism: ideology delayed a public-health response to one of the worst epidemics of the postwar decades.", "exp_zh": "艾滋病危机暴露了1980年代保守主义的道德盲区：意识形态拖延了对战后最严重疫情之一的公共卫生应对。", "page": 985, "img": {"file": "img:f2_1803", "credit": "图源：Henretta《America's History》第8版 p.985"}}, {"id": "p9-013", "period": 9, "topic_en": "The shift from manufacturing to a service economy", "topic_zh": "从制造业向服务经济的转型", "year": null, "year_text": "1970s–1980s", "who": [], "who_zh": [], "what_en": "American heavy industry lost market share to West Germany and Japan; by 1985 the United States became a debtor nation, more Americans worked for McDonald's than in the steel industry, and financial services, medical services, and computer technology became the leading growth sectors.", "what_zh": "美国重工业把市场份额输给西德和日本；到1985年美国成为债务国，在麦当劳工作的人超过钢铁业工人，金融服务、医疗服务和计算机技术成为增长主导部门。", "cause_en": "Foreign competition undercut American manufacturers with cheaper, better-designed products, while managers cut costs, productivity growth slowed from 3 percent to 1 percent a year, and wages stagnated.", "cause_zh": "外国竞争以更便宜、设计更好的产品冲击美国制造商，管理层压缩成本，生产率增速从3%降至1%，工资停滞不前。", "sig_en": "The transformation from making things to producing services reshaped long-term U.S. competitiveness and the value of the dollar; productivity gains went to owners, shareholders, and executives rather than workers.", "sig_zh": "从制造物品到生产服务的转型重塑了美国长期竞争力和美元价值；生产率收益流向所有者、股东和高管，而非工人。", "exp_en": "Deindustrialization was the economic underside of the 1980s boom: prosperity returned, but its benefits flowed to services and finance while union-protected factory jobs disappeared.", "exp_zh": "去工业化是1980年代繁荣的阴暗面：繁荣回来了，但收益流向服务业和金融业，有工会保护的工厂岗位消失了。", "page": 987, "img": {"file": "img:f2_1809", "credit": "图源：Henretta《America's History》第8版 p.987"}}, {"id": "p9-014", "period": 9, "topic_en": "The personal computer revolution", "topic_zh": "个人电脑革命", "year": 1976, "year_text": "1976 (Apple founded); Macintosh 1984", "who": ["Steve Jobs", "Steve Wozniak", "Bill Gates", "Paul Allen"], "who_zh": ["史蒂夫·乔布斯", "史蒂夫·沃兹尼亚克", "比尔·盖茨", "保罗·艾伦"], "what_en": "Jobs and Wozniak founded Apple in 1976 and the 1984 Macintosh became the first runaway PC success; Gates and Allen founded Microsoft in 1975, and by 2000 its software ran nine of every ten U.S. personal computers.", "what_zh": "乔布斯和沃兹尼亚克1976年创立苹果，1984年麦金塔成为首款大获成功的个人电脑；盖茨和艾伦1975年创立微软，到2000年其软件运行在十分之九的美国个人电脑上。", "cause_en": "The microprocessor (1971) shrank computing power to chips the size of the letter O, and the two pairs of entrepreneurs saw that software was the key to putting a personal computer on every desk and in every home.", "cause_zh": "微处理器（1971年）把计算能力压缩到字母O大小的芯片上，两对创业者意识到软件是实现“每张桌上、每个家庭一台个人电脑”目标的关键。", "sig_en": "In three decades the computer moved from a few military research centers to millions of homes — ironically, government research and funding had played an enormous role in developing this icon of free-market capitalism.", "sig_zh": "三十年间电脑从少数军事研究中心走进千家万户——颇具讽刺的是，政府研究和资助在这一自由市场资本主义象征的发展中起了巨大作用。", "exp_en": "The PC revolution made technology, not manufacturing, the engine of American growth — and made billionaires of the dropouts who bet on software.", "exp_zh": "个人电脑革命使技术而非制造业成为美国增长的引擎——也让押注软件的辍学生成了亿万富翁。", "page": 989, "src": {"text": "A computer frees people from much of the menial work. . . . Remember computers are tools. Tools help us do our work better.", "attr": "Interview with Steve Jobs, February 1, 1985"}}, {"id": "p9-015", "period": 9, "topic_en": "The Strategic Defense Initiative ('Star Wars')", "topic_zh": "战略防御计划（“星球大战”）", "year": null, "year_text": "early 1980s", "who": ["Ronald Reagan", "Caspar Weinberger"], "who_zh": ["罗纳德·里根", "卡斯帕·温伯格"], "what_en": "Reagan proposed the Strategic Defense Initiative, a satellite-based system that would theoretically destroy nuclear missiles in flight; scientists doubted its viability and it was never built.", "what_zh": "里根提出战略防御计划——一种理论上能在飞行中摧毁核导弹的天基系统；科学家质疑其可行性，该计划从未建成。", "cause_en": "Rejecting detente and containment, Reagan sought to defeat, not merely contain, the Soviet Union; Defense Secretary Caspar Weinberger reasoned the arms buildup would force Moscow into an economy-straining arms race and domestic unrest.", "cause_zh": "里根拒绝缓和与遏制，主张击败而非仅仅遏制苏联；国防部长温伯格认为军备扩张将迫使莫斯科陷入拖垮经济的军备竞赛并引发国内动荡。", "sig_en": "SDI became the most controversial symbol of Reagan's military buildup, which — combined with the Soviet system's internal decay and Gorbachev's reforms — helped end the Cold War even though the system itself never worked.", "sig_zh": "SDI成为里根军事扩张最具争议的象征；尽管系统本身从未奏效，这场军备扩张与苏联体制内部衰朽、戈尔巴乔夫改革合力终结了冷战。", "exp_en": "Star Wars mattered less as a weapon than as pressure: whether or not it could work, Moscow had to treat the American technological challenge as real.", "exp_zh": "“星球大战”作为武器的意义不如作为压力的意义：不管它能否奏效，莫斯科都必须把美国的技术挑战当真。", "page": 992}, {"id": "p9-016", "period": 9, "topic_en": "U.S. intervention in Nicaragua: Sandinistas and Contras", "topic_zh": "美国干预尼加拉瓜：桑地诺派与反政府武装", "year": 1979, "year_text": "1979 (Sandinistas take power); civil war 1979–1989", "who": ["Anastasio Somoza"], "who_zh": ["安纳斯塔西奥·索摩查"], "what_en": "After the left-wing Sandinistas overthrew U.S.-backed strongman Anastasio Somoza in 1979, Reagan funded the Contra rebels against the Sandinista government; the civil war lasted until the Sandinistas lost the 1990 elections.", "what_zh": "1979年左翼桑地诺派推翻美国支持的索摩查政权后，里根资助反政府武装对抗桑地诺政府；内战持续到桑地诺派在1990年大选中落败。", "cause_en": "Reagan backed CIA initiatives to roll back Soviet influence in the developing world, siding with right-wing regimes and movements wherever left-wing forces sought Soviet support — in Guatemala, Nicaragua, and El Salvador alike.", "cause_zh": "里根支持中情局在发展中国家遏制苏联影响的行动：凡是左翼势力寻求苏联支持的地方——危地马拉、尼加拉瓜、萨尔瓦多——美国都站在右翼政权和势力一边。", "sig_en": "Reagan blocked Soviet influence but damaged local communities and America's international reputation, as in Vietnam; some Contra aid was provided illegally, producing the Iran-Contra scandal.", "sig_zh": "里根阻断了苏联影响，却如越南一样损害了当地社会和美国的国际声誉；部分反政府武装援助是非法提供的，酿成了伊朗门丑闻。", "exp_en": "Central America was where Reagan's rollback doctrine met its messiest test: the U.S. sided with dictatorships and death squads to keep leftists from Soviet arms.", "exp_zh": "中美洲是里根“回滚”战略最混乱的试验场：为阻止左翼获得苏联武器，美国站到了独裁政权和敢死队一边。", "page": 992}, {"id": "p9-017", "period": 9, "topic_en": "The Iran-Contra affair", "topic_zh": "伊朗门事件", "year": 1986, "year_text": "1986–1987 (televised hearings 1987)", "who": ["Oliver North", "Ronald Reagan"], "who_zh": ["奥利弗·诺斯", "罗纳德·里根"], "what_en": "Marine Lt. Col. Oliver North secretly sold arms to Iran and diverted the profits to the Nicaraguan Contras in defiance of a congressional ban; the 1987 televised hearings led to prosecutions of North and other officials.", "what_zh": "海军陆战队中校奥利弗·诺斯秘密向伊朗出售武器，把利润转给尼加拉瓜反政府武装，违反国会禁令；1987年电视听证会导致诺斯等官员被起诉。", "cause_en": "Reagan's determination to oppose left-wing movements in Central America collided with Congress's ban on Contra aid; North acted with the tacit or explicit consent of high-ranking officials, including the president, who had long denounced Iran.", "cause_zh": "里根反对中美洲左翼运动的决心与国会禁止援助反政府武装的法令相冲突；诺斯在包括总统在内的高官默许或明示同意下行动，而总统长期谴责伊朗。", "sig_en": "The scandal weakened Reagan domestically — when asked about North's illegal acts he answered 'I don't remember,' and he proposed no bold domestic initiatives in his last two years — though North emerged from the hearings a populist hero among conservatives.", "sig_zh": "丑闻削弱了里根的国内地位——被问及诺斯的非法行为时他回答“我不记得了”，最后两年再无大胆国内政策——而诺斯却在听证会后成为保守派心中的民粹英雄。", "exp_en": "Iran-Contra showed the collision between Reagan's anti-communist crusade and constitutional limits: the White House ran a secret foreign policy Congress had explicitly forbidden.", "exp_zh": "伊朗门显示里根反共运动与宪法限制的碰撞：白宫推行了一套国会明令禁止的秘密外交政策。", "page": 993, "img": {"file": "img:f2_1827", "credit": "图源：Henretta《America's History》第8版 p.993"}}, {"id": "p9-018", "period": 9, "topic_en": "Mikhail Gorbachev: glasnost and perestroika", "topic_zh": "米哈伊尔·戈尔巴乔夫：开放与改革", "year": 1985, "year_text": "1985 (Gorbachev takes power)", "who": ["Mikhail Gorbachev", "Ronald Reagan"], "who_zh": ["米哈伊尔·戈尔巴乔夫", "罗纳德·里根"], "what_en": "Soviet leader Mikhail Gorbachev, who became Communist Party general secretary in 1985, introduced glasnost (openness) and perestroika (economic restructuring), encouraging widespread criticism of rigid Communist institutions; by 1987 he and Reagan agreed to eliminate all intermediate-range nuclear missiles in Europe.", "what_zh": "1985年就任苏共总书记的米哈伊尔·戈尔巴乔夫推行开放（glasnost）与改革（perestroika，经济重组），鼓励广泛批评僵化的共产党体制；到1987年他与里根同意消除欧洲所有中程核导弹。", "cause_en": "The inefficient Soviet command economy fell further behind capitalist societies, and the disastrous 1979 invasion of Afghanistan drained money, morale, and popular support; Gorbachev also sought eased U.S. tensions to press his domestic reforms.", "cause_zh": "低效的苏联计划经济越来越落后于资本主义社会，1979年灾难性的入侵阿富汗耗尽资金、士气和民众支持；戈尔巴乔夫也希望缓和美苏关系以推进国内改革。", "sig_en": "Glasnost unleashed popular criticism that, with the 1989 Velvet Revolutions and the failed August 1991 coup, broke Communist Party dominance and led to the USSR's formal dissolution on December 25, 1991.", "sig_zh": "开放政策释放的民众批评，加上1989年天鹅绒革命和1991年8月未遂政变，打破了共产党统治，导致苏联于1991年12月25日正式解体。", "exp_en": "Gorbachev tried to save socialism by reforming it, but openness exposed the system's illegitimacy faster than restructuring could fix its economy.", "exp_zh": "戈尔巴乔夫想通过改革拯救社会主义，但开放暴露体制非法性的速度超过了重组修复经济的速度。", "page": 993, "img": {"file": "img:f2_1827", "credit": "图源：Henretta《America's History》第8版 p.993"}}, {"id": "p9-019", "period": 9, "topic_en": "The fall of the Berlin Wall and the collapse of the Soviet Union", "topic_zh": "柏林墙倒塌与苏联解体", "year": 1989, "year_text": "1989 (Berlin Wall); December 25, 1991 (USSR dissolved)", "who": ["Boris Yeltsin", "Mikhail Gorbachev"], "who_zh": ["鲍里斯·叶利钦", "米哈伊尔·戈尔巴乔夫"], "what_en": "In November 1989 jubilant Germans tore down the Berlin Wall, symbolizing the end of Communist rule in Central Europe; after a failed August 1991 coup, the USSR formally dissolved on December 25, 1991, replaced by an eleven-member Commonwealth of Independent States.", "what_zh": "1989年11月欢欣鼓舞的德国人推倒柏林墙，象征中欧共产党统治的终结；1991年8月政变失败后，苏联于1991年12月25日正式解体，由十一国组成的独立国家联合体取代。", "cause_en": "Gorbachev's reforms exposed the Soviet system's flaws; Eastern Europeans demanded Communist governments' ouster in peaceful Velvet Revolutions that Soviet troops, unlike in 1956 and 1968, did not crush; popular opposition led by Boris Yeltsin thwarted the 1991 hard-line coup.", "cause_zh": "戈尔巴乔夫的改革暴露了苏联体制的缺陷；东欧人以和平的“天鹅绒革命”要求共产党政府下台，苏军不像1956和1968年那样镇压；叶利钦领导的民众反对挫败了1991年强硬派政变。", "sig_en": "The nearly fifty-year Cold War ended; the text stresses that internal Soviet weakness mattered more than U.S. pressure, though conservatives celebrated the outcome as vindication of free-market capitalism after $4 trillion spent on nuclear weapons.", "sig_zh": "近五十年的冷战结束；教材强调苏联内部虚弱比美国外部压力更重要，尽管保守派把这一结果庆祝为自由市场资本主义的胜利——美国曾为核武器花费约4万亿美元。", "exp_en": "The Cold War ended not with a battle but with an implosion: the Soviet system collapsed under its own contradictions once reform removed the fear that held it together.", "exp_zh": "冷战不是以一场战役而是以内爆结束：一旦改革拿掉了维系体制的恐惧，苏联体系就在自身矛盾下崩塌。", "page": 994, "img": {"file": "img:f2_1829", "credit": "图源：Henretta《America's History》第8版 p.994"}}, {"id": "p9-020", "period": 9, "topic_en": "The election of 1988 and George H. W. Bush", "topic_zh": "1988年大选与老布什", "year": 1988, "year_text": "November 1988", "who": ["George H. W. Bush", "Michael Dukakis", "Dan Quayle", "Jesse Jackson"], "who_zh": ["乔治·H·W·布什", "迈克尔·杜卡基斯", "丹·奎尔", "杰西·杰克逊"], "what_en": "George H. W. Bush won the presidency with 53 percent of the vote, defeating Michael Dukakis; he picked little-known Indiana senator Dan Quayle as running mate to secure the Christian family values vote.", "what_zh": "乔治·H·W·布什以53%得票率击败迈克尔·杜卡基斯当选总统；他选择名不见经传的印第安纳州参议员丹·奎尔作竞选搭档，以争取基督徒家庭价值观选票。", "cause_en": "Bush's fierce loyalty to Reagan won him the nomination over televangelist Pat Robertson's primary challenge; Dukakis, a northeastern liberal, could not win back southern whites, blue-collar Catholics, and suburbanites, and Jesse Jackson's historic primary bid fell short.", "cause_zh": "布什对里根的忠诚使他在提名战中击败电视布道家帕特·罗伯逊的挑战；东北部自由派杜卡基斯无法赢回南方白人、蓝领天主教徒和郊区居民，杰西·杰克逊具有历史意义的初选努力也功亏一篑。", "sig_en": "The election confirmed the Religious Right as a major force in Republican politics and a new pattern: every four years Americans would refight the battles of the 1960s, liberals versus conservatives, in what Bush called a coming 'new world order.'", "sig_zh": "这次大选确认宗教右翼成为共和党政治的重要力量，也确认了新模式：每四年美国人就重打1960年代的战争——自由派对保守派，迎接布什所说的“新世界秩序”。", "exp_en": "Bush was Reagan's heir but not a movement conservative: his victory ratified the Reagan realignment while showing the Religious Right could now demand a seat at the ticket.", "exp_zh": "布什是里根的继承人却非运动型保守派：他的胜利批准了里根重组，也显示宗教右翼已能在候选人名单上要求一席之地。", "page": 996, "img": {"file": "img:f2_1836", "credit": "图源：Henretta《America's History》第8版 p.996"}}, {"id": "p9-021", "period": 9, "topic_en": "The Persian Gulf War", "topic_zh": "海湾战争", "year": 1990, "year_text": "August 1990–1991", "who": ["George H. W. Bush", "Saddam Hussein"], "who_zh": ["乔治·H·W·布什", "萨达姆·侯赛因"], "what_en": "After Iraq invaded Kuwait in August 1990, President Bush built a thirty-four-nation UN coalition that quickly liberated Kuwait in 1991, then imposed sanctions and weapons inspections on Iraq under UN Resolution 687.", "what_zh": "1990年8月伊拉克入侵科威特后，布什总统组建三十四国联合国联军，1991年迅速解放科威特，随后依据联合国687号决议对伊拉克实施制裁和武器核查。", "cause_en": "The United States sought to preserve Western access to oil — Saudi Arabia held one-fifth of known reserves — and Saddam's invasion threatened the regional balance; the House authorized force 252–182 and the Senate 52–47, dividing mostly along party lines.", "cause_zh": "美国要维护西方获取石油的通道——沙特拥有已知储量的五分之一——萨达姆入侵威胁地区均势；众议院以252比182、参议院以52比47授权动武，基本按党派划线。", "sig_en": "'By God, we've kicked the Vietnam syndrome once and for all,' Bush declared as his approval soared; but to avoid a protracted struggle he stopped short of occupying Iraq, leaving Saddam in power — the pretext for his son's far bloodier 2003 war.", "sig_zh": "布什的支持率飙升，他宣称“我们终于永远摆脱了越南综合征”；但为避免长期纠缠，他止步于占领伊拉克，留下萨达姆掌权——这成为其子2003年那场血腥得多的战争的借口。", "why_term": "Vietnam syndrome", "why_term_q": "海湾战争胜利后，布什宣称美国终于摆脱了 ______。", "exp_en": "The Gulf War was the first post–Cold War test of American power: a short, UN-blessed victory that made intervention look easy — a lesson the next generation would misapply in Iraq.", "exp_zh": "海湾战争是后冷战时代美国实力的首次检验：一场短暂、获联合国背书的胜利，让干预看起来很容易——下一代在伊拉克误用了这一教训。", "page": 998, "img": {"file": "img:f2_1842", "credit": "图源：Henretta《America's History》第8版 p.998"}}, {"id": "p9-022", "period": 9, "topic_en": "Globalization", "topic_zh": "全球化", "year": null, "year_text": "1990s–2000s", "who": ["Bill Clinton"], "who_zh": ["比尔·克林顿"], "what_en": "After the Cold War, capitalism spread worldwide with surging trade, integrated financial markets, and communications technology; the leading capitalist nations managed the system through the G7/G8, the World Bank, the IMF, and the WTO.", "what_zh": "冷战后，资本主义在全球迅速扩散，贸易激增、金融市场一体化、通信技术普及；主要资本主义国家通过七国集团/八国集团、世界银行、国际货币基金组织和世贸组织管理这一体系。", "cause_en": "The end of the Cold War shattered barriers to trade and capitalist development, while satellites, fiber-optic cables, and open financial markets shrank the world's physical spaces to a degree unimaginable a generation earlier.", "cause_zh": "冷战结束打破了贸易和资本主义发展的壁垒，卫星、光纤和开放的金融市场把世界物理空间压缩到一代人前难以想象的程度。", "sig_en": "Globalization brought cheaper goods and new markets but also shuttered U.S. factories, made the economy crash-prone — the 1997 Asian crisis and the 2008 global collapse — and its openness and interconnectivity made terrorism like 9/11 possible.", "sig_zh": "全球化带来廉价商品和新市场，也关闭了美国工厂，使经济更易崩盘——1997年亚洲金融危机和2008年全球崩溃——其开放与互联也使9/11式恐怖主义成为可能。", "exp_en": "'Profound and powerful forces are shaking and remaking our world,' Clinton said in 1993; globalization forced every president after the Cold War to answer whether America could make change its friend and not its enemy.", "exp_zh": "克林顿1993年说“深刻而强大的力量正在震撼和重塑我们的世界”；全球化迫使冷战后每位总统回答：美国能否让变革成为朋友而非敌人。", "page": 1004, "src": {"text": "The one thing that I am quite sure of is that interdependence is not a choice, it's not a policy, it is the inevitable condition of our time.", "attr": "Former president Bill Clinton, speech at Guildhall, London, 2006"}, "img": {"file": "img:f2_1863", "credit": "图源：Henretta《America's History》第8版 p.1004"}}, {"id": "p9-023", "period": 9, "topic_en": "The World Trade Organization and the Battle of Seattle", "topic_zh": "世界贸易组织与西雅图之战", "year": 1995, "year_text": "1995 (WTO founded); Seattle protests 1999", "who": [], "who_zh": [], "what_en": "In 1995 GATT evolved into the World Trade Organization, with nearly 150 nations formalizing trade agreements; on November 30, 1999 more than 50,000 protesters shut down the WTO's Seattle meeting, fearing free trade benefited multinational corporations while hurting workers.", "what_zh": "1995年关贸总协定演变为世界贸易组织，近150个成员国规范贸易协定；1999年11月30日五万多名抗议者瘫痪了西雅图WTO会议，担心自由贸易只惠及跨国公司而伤害工人。", "cause_en": "As global trade rules were written to lower tariffs and open markets, activists, labor, and environmental groups argued the system served corporations over workers, developing nations, and the environment — demanding trade be an instrument for equitable, sustainable development.", "cause_zh": "随着全球贸易规则不断降低关税、开放市场，活动家、劳工和环保团体认为这一体系服务于公司而非工人、发展中国家和环境——要求贸易成为实现公平可持续发展的工具。", "sig_en": "The Battle of Seattle made globalization's discontents visible and began a pattern of protests at WTO and World Bank meetings worldwide.", "sig_zh": "西雅图之战使全球化的不满公开化，开启了在世贸组织和世界银行会议上抗议的模式。", "exp_en": "Seattle was globalization's coming-out party for its critics: the first mass demonstration that the rules of world trade were themselves a political choice.", "exp_zh": "西雅图是全球化批评者的亮相派对：首次大规模示威表明世界贸易规则本身就是一种政治选择。", "page": 1004, "img": {"file": "img:f2_1863", "credit": "图源：Henretta《America's History》第8版 p.1004"}}, {"id": "p9-024", "period": 9, "topic_en": "The European Union", "topic_zh": "欧盟", "year": 1992, "year_text": "1992 (EU created); euro introduced 2002", "who": [], "who_zh": [], "what_en": "In 1992 Western European nations created the European Union, moving toward a single federal state; by the late 1990s it embraced more than twenty countries and 450 million people, and in 2002 introduced the euro, which soon rivaled the dollar and the yen.", "what_zh": "1992年西欧国家创建欧盟，向单一联邦国家迈进；到1990年代末欧盟囊括二十多个国家、4.5亿人口，2002年启用欧元，很快与美元、日元分庭抗礼。", "cause_en": "With the Cold War's bipolar order gone, Europe integrated into a united trading bloc and economic engine accounting for a fifth of all global imports and exports.", "cause_zh": "冷战两极格局消失后，欧洲整合成统一贸易集团和经济引擎，占全球进出口的五分之一。", "sig_en": "The EU emerged as an economic juggernaut and trading rival to the United States — but, militarily, a secondary power with a suspicion of warfare, posing new dilemmas for American officials in a multipolar world.", "sig_zh": "欧盟崛起为经济巨头和美国的贸易对手——但在军事上是次要力量且厌恶战争，在多极世界给美国官员带来新难题。", "exp_en": "European integration showed globalization's other pole: where America globalized through corporations, Europe did it through institutions.", "exp_zh": "欧洲一体化显示了全球化的另一极：美国通过公司实现全球化，欧洲通过制度实现。", "page": 1005, "img": {"file": "img:f2_1866", "credit": "图源：Henretta《America's History》第8版 p.1005"}}, {"id": "p9-025", "period": 9, "topic_en": "The economic rise of China", "topic_zh": "中国经济崛起", "year": null, "year_text": "2000–2008", "who": [], "who_zh": [], "what_en": "Between 2000 and 2008 China quadrupled its GDP with growth near 10 percent a year; still Communist-ruled, it embraced capitalism, exporting inexpensive goods Americans eagerly bought while deliberately keeping its currency weak against the dollar.", "what_zh": "2000至2008年中国GDP翻了两番，年增速近10%；仍由共产党执政的中国拥抱资本主义，向美国出口美国人热衷购买的廉价商品，同时刻意压低人民币对美元汇率。", "cause_en": "Post–Cold War opening plus a state-led export strategy turned China into the world's fastest-rising economic power; keeping its currency weak ensured its exports stayed cheap in the United States, and it recycled earnings by purchasing American debt.", "cause_zh": "冷战后的开放加上国家主导的出口战略使中国成为世界增长最快的经济体；压低汇率保证了其出口在美国保持廉价，并用收益购买美国国债。", "sig_en": "The relationship shrank America's manufacturing base, cost jobs and communities, and left China owning nearly 25 percent of total U.S. debt — an influence over the U.S. currency supply many economists call unwise.", "sig_zh": "这一关系压缩了美国制造业基础、夺走就业和社区，使中国持有近四分之一的美国国债——许多经济学家认为让一国对美国货币供应有如此大影响是不明智的。", "exp_en": "China was globalization's great paradox for America: a Communist Party running a capitalist export machine that American consumers loved and American workers feared.", "exp_zh": "中国是美国全球化的大悖论：共产党经营着一台资本主义出口机器，美国消费者热爱它，美国工人害怕它。", "page": 1008}, {"id": "p9-026", "period": 9, "topic_en": "The North American Free Trade Agreement (NAFTA)", "topic_zh": "北美自由贸易协定", "year": 1993, "year_text": "1993 (signed and ratified)", "who": [], "who_zh": [], "what_en": "In 1993 the United States, Canada, and Mexico signed NAFTA, which Congress ratified, envisioning the eventual creation of a free-trade zone covering all of North America.", "what_zh": "1993年美、加、墨签署北美自由贸易协定并经国会批准，设想最终建成覆盖整个北美洲的自由贸易区。", "cause_en": "As regional economies integrated worldwide, the United States sought to offset the economic clout of the European bloc with its own North American counterpart.", "cause_zh": "随着全球区域经济一体化，美国寻求以北美版本对冲欧洲集团的经济影响力。", "sig_en": "NAFTA deepened continental economic integration — and, critics argued, accelerated the outsourcing of U.S. manufacturing jobs to Mexico's low-wage plants.", "sig_zh": "北美自由贸易协定深化了大陆经济一体化——批评者认为它也加速了美国制造业岗位向墨西哥低工资工厂外流。", "why_term": "free-trade zone", "why_term_q": "北美自由贸易协定设想最终建成覆盖整个北美洲的 ______。", "exp_en": "NAFTA made free trade a domestic political fault line: supporters saw efficiency, opponents saw factory towns emptied.", "exp_zh": "北美自由贸易协定使自由贸易成为国内政治断层线：支持者看到效率，反对者看到工厂城镇被掏空。", "page": 1010, "img": {"file": "img:f2_1900", "credit": "图源：Henretta《America's History》第8版 p.1010"}}, {"id": "p9-027", "period": 9, "topic_en": "Multinational corporations and outsourcing", "topic_zh": "跨国公司与外包", "year": null, "year_text": "1970–2000", "who": [], "who_zh": [], "what_en": "Corporations with offices and factories in multiple countries exploded from 7,000 in 1970 to 63,000 in 2000; firms like Nike closed U.S. factories and outsourced manufacturing — and later skilled jobs — to low-wage plants in Mexico, Eastern Europe, and Asia.", "what_zh": "在多国设有分支和工厂的公司从1970年的7000家激增到2000年的63000家；耐克等公司关闭美国工厂，把制造——后来连技术岗位也——外包到墨西哥、东欧和亚洲的低工资工厂。", "cause_en": "Beyond seeking new markets, corporations sought ever-cheaper labor; by 2005 Nike ran 700 factories worldwide employing 650,000 workers, most with low wages, harsh conditions, and no health or pension benefits.", "cause_zh": "企业除开拓新市场外，还寻求更低的劳动力成本；到2005年耐克在全球有700家工厂、65万工人，大多工资低、条件差、无医保和养老金。", "sig_en": "Outsourcing hollowed out American manufacturing communities while enriching shareholders, becoming a central grievance of globalization's critics and a driver of wage stagnation.", "sig_zh": "外包掏空了美国制造业社区，却让股东致富，成为全球化批评者的核心不满和工资停滞的推手。", "exp_en": "'McWorld' — McDonald's growing from 1,000 foreign outlets in 1980 to nearly 13,000 twenty years later — became shorthand for a globalization built by American corporations.", "exp_zh": "“麦当劳世界”——麦当劳海外门店从1980年1000家增至二十年后近13000家——成为美国公司主导的全球化的代名词。", "page": 1010, "img": {"file": "img:f2_1900", "credit": "图源：Henretta《America's History》第8版 p.1010"}}, {"id": "p9-028", "period": 9, "topic_en": "The Internet and the World Wide Web", "topic_zh": "互联网与万维网", "year": 1991, "year_text": "ARPANET late 1960s; World Wide Web 1991", "who": [], "who_zh": [], "what_en": "The Internet grew out of the Defense Department's ARPANET, developed with MIT in the late 1960s; the graphics-based World Wide Web debuted in 1991, and by 2011 some 78 percent of Americans were online.", "what_zh": "互联网源于国防部与麻省理工在1960年代末共建的阿帕网；图形化万维网1991年问世，到2011年约78%的美国人上网。", "cause_en": "Military-funded research created a decentralized network for scientists and contractors to exchange data and email; the Web's easy access to documents and pictures gave the Internet popular appeal and commercial possibility, with e-commerce nearing $500 billion by 2010.", "cause_zh": "军方资助的研究为科学家和承包商建起交换数据和邮件的去中心化网络；万维网便捷的文档图片访问赋予互联网大众吸引力和商业前景，2010年电子商务接近5000亿美元。", "sig_en": "Like unimpeded trade, the Internet deepened globalization, transforming how Americans shopped, worked, learned, and stayed in touch — while draining newspapers of readers and killing dozens of papers between 2000 and 2010.", "sig_zh": "互联网如自由贸易般深化了全球化，改变了美国人的购物、工作、学习和联络方式——也抽干了报纸读者，2000至2010年间数十家大中型报纸倒闭。", "exp_en": "The Web proved instantly democratic, giving ordinary people easy access to knowledge — and giving terrorists, shoppers, and protesters the same tools.", "exp_zh": "万维网即刻展现出民主性，让普通人便捷获取知识——也让恐怖分子、购物者和抗议者拿到同样的工具。", "page": 1012, "img": {"file": "img:f2_1905", "credit": "图源：Henretta《America's History》第8版 p.1012"}}, {"id": "p9-029", "period": 9, "topic_en": "The September 11, 2001 terrorist attacks", "topic_zh": "九一一恐怖袭击", "year": 2001, "year_text": "September 11, 2001", "who": ["Al Qaeda", "Osama bin Laden"], "who_zh": ["基地组织", "奥萨马·本·拉登"], "what_en": "On September 11, 2001, nineteen Al Qaeda terrorists hijacked four jets, flying two into the World Trade Center towers, one into the Pentagon, and crashing a fourth in Pennsylvania after passengers fought back; about 2,900 people died.", "what_zh": "2001年9月11日，十九名基地组织恐怖分子劫持四架客机，两架撞入世贸双子塔，一架撞入五角大楼，第四架在乘客反抗后坠毁于宾夕法尼亚；约2900人死亡。", "cause_en": "Osama bin Laden's Al Qaeda, trained in Afghan camps, exploited globalization's openness — email, cell phones, flight schools in the United States — and was enraged by the continued U.S. military presence in Saudi Arabia after the Gulf War; Clinton-era strikes on Afghan bases had failed to disrupt the network.", "cause_zh": "本·拉登的基地组织在阿富汗营地受训，利用全球化的开放——电子邮件、手机、美国境内的飞行学校——并对海湾战争后美军继续驻扎沙特怒不可遏；克林顿时代对阿富汗基地的空袭未能打乱该网络。", "sig_en": "The attacks ended the post–Cold War calm, launched Bush's war on terror, and in May 2011 U.S. Special Forces finally found and killed bin Laden in Pakistan, where he had hidden for years.", "sig_zh": "袭击终结了后冷战的平静，开启布什的反恐战争；2011年5月美军特种部队终于在巴基斯坦找到并击毙躲藏多年的本·拉登。", "exp_en": "9/11 was globalization's dark side made visible: the same openness that moved goods, money, and people could move terrorists.", "exp_zh": "9/11是全球化阴暗面的具象化：流动商品、金钱和人口的开放，同样能流动恐怖分子。", "page": 1002}, {"id": "p9-030", "period": 9, "topic_en": "The USA PATRIOT Act", "topic_zh": "《爱国者法案》", "year": 2001, "year_text": "2001", "who": ["George W. Bush"], "who_zh": ["乔治·W·布什"], "what_en": "In 2001 Congress passed the USA PATRIOT Act with little debate, granting the administration sweeping authority to monitor citizens and apprehend suspected terrorists.", "what_zh": "2001年国会几乎未经辩论就通过《爱国者法案》，授予政府广泛权力监控公民、抓捕恐怖嫌疑人。", "cause_en": "Bush declared the terrorist threat too big to be contained by ordinary law enforcement and wanted the government's powers of domestic surveillance placed on a wartime footing after 9/11.", "cause_zh": "布什宣称恐怖威胁太大，普通执法手段不够，要求把政府国内监控权置于战时状态。", "sig_en": "The act marked a major expansion of federal surveillance power at the expense of civil liberties, a centerpiece of the domestic war on terror.", "sig_zh": "该法以牺牲公民自由为代价大幅扩张了联邦监控权，成为国内反恐战争的核心。", "exp_en": "The PATRIOT Act shows how crises rewrite the balance between security and liberty: fear made sweeping surveillance politically unstoppable.", "exp_zh": "《爱国者法案》显示危机如何重写安全与自由的平衡：恐惧使全面监控在政治上不可阻挡。", "page": 1028, "img": {"file": "img:f2_1955", "credit": "图源：Henretta《America's History》第8版 p.1028"}}, {"id": "p9-031", "period": 9, "topic_en": "The Iraq War and the Bush doctrine", "topic_zh": "伊拉克战争与布什主义", "year": 2003, "year_text": "March 2003 (invasion)", "who": ["George W. Bush", "Saddam Hussein"], "who_zh": ["乔治·W·布什", "萨达姆·侯赛因"], "what_en": "In March 2003 Bush invaded Iraq without a legitimizing UN resolution, toppling Saddam Hussein within weeks; the Pentagon had made no provision for post-conflict operations, and a Sunni-led insurgency soon bogged U.S. forces down.", "what_zh": "2003年3月布什在没有联合国合法化决议的情况下入侵伊拉克，数周内推翻萨达姆；五角大楼未做战后安排，逊尼派主导的叛乱很快拖住美军。", "cause_en": "Under the Bush doctrine of anticipatory self-defense, the administration called Iraq a 'grave and gathering danger,' named it with Iran and North Korea an 'axis of evil,' and saw a chance to democratize the Middle East and secure its oil — Iraq was 'unfinished business' from the 1991 Gulf War.", "cause_zh": "根据“先发制人自卫”的布什主义，政府称伊拉克是“严重且不断增长的危险”，与伊朗、朝鲜并称“邪恶轴心”，并视之为在中东推广民主、保障石油的机会——伊拉克是1991年海湾战争留下的“未竟事业”。", "sig_en": "The war poisoned relations with France and Germany, drew condemnation even from Mexico and Canada, and by 2004 had cost over $100 billion with more than 1,000 Americans dead — yet withdrawal meant chaos, so Bush insisted on staying the course.", "sig_zh": "战争毒化了与法德的关系，连墨西哥和加拿大都谴责入侵，到2004年已耗费超1000亿美元、1000多名美军生命——但撤军意味着混乱，于是布什坚持“坚持到底”。", "why_term": "axis of evil", "why_term_q": "2002年布什把伊朗、朝鲜、伊拉克称为 ______。", "exp_en": "Iraq was preventive war's test case: launched on the theory that American power could democratize a region, it instead demonstrated the limits of military force against nationalism and insurgency.", "exp_zh": "伊拉克是预防性战争的试验品：基于美国力量能使一地区民主化的理论发动，却证明了军事力量在民族主义和叛乱面前的限度。", "page": 1028, "img": {"file": "img:f2_1955", "credit": "图源：Henretta《America's History》第8版 p.1028"}}, {"id": "p9-032", "period": 9, "topic_en": "The Abu Ghraib prison scandal", "topic_zh": "阿布格莱布监狱丑闻", "year": 2004, "year_text": "2004", "who": [], "who_zh": [], "what_en": "In 2004 photographs showed American guards at Baghdad's Abu Ghraib prison abusing and torturing suspected insurgents, shocking the world.", "what_zh": "2004年照片曝光美军看守在巴格达阿布格莱布监狱虐待、折磨被疑为叛乱分子的囚犯，震惊世界。", "cause_en": "In a war against insurgents, U.S. forces came under fire from both Sunnis and Shiites while Al Qaeda supporters streamed across unguarded borders; as the text notes, no occupation force in such a war comes out with clean hands.", "cause_zh": "在反叛乱战争中，美军同时遭到逊尼派和什叶派攻击，基地组织支持者越过无人守卫的边境涌入；如教材所言，这种战争中没有占领军能全身而退。", "sig_en": "For Muslims the images were final proof of American treachery; at that low point the United States had spent upward of $100 billion with more than 1,000 soldiers dead and 10,000 wounded, deepening opposition to the war at home and abroad.", "sig_zh": "对穆斯林而言这些照片是美国背信弃义的最终证据；在这一低谷美国已花费超1000亿美元，阵亡逾千人、受伤一万，加深了国内外对战争的反对。", "exp_en": "Abu Ghraib destroyed America's moral standing in the war on terror: the images traveled farther and lasted longer than any battlefield victory.", "exp_zh": "阿布格莱布摧毁了美国在反恐战争中的道德地位：这些照片比任何战场胜利传得更远、留存更久。", "page": 1029, "img": {"file": "img:f2_1959", "credit": "图源：Henretta《America's History》第8版 p.1029"}}, {"id": "p9-033", "period": 9, "topic_en": "The Immigration and Nationality Act of 1965 and the new immigration wave", "topic_zh": "1965年《移民与国籍法》与新移民潮", "year": 1965, "year_text": "1965 (Hart-Celler Act)", "who": [], "who_zh": [], "what_en": "The Hart-Celler Act eliminated the 1924 quota system favoring Northern Europe; of the 77-million U.S. population increase between 1970 and 2000, immigrants accounted for 28 million, overwhelmingly from Latin America (16 million) and East Asia (9 million).", "what_zh": "哈特-塞勒法废除了偏袒北欧的1924年配额制；1970至2000年美国7700万人口增长中，移民占2800万，绝大多数来自拉美（1600万）和东亚（900万）。", "cause_en": "Great Society liberals wanted a fairer, skills-based system; a provision admitting immediate family members outside the numerical limit had far-reaching, unintended consequences, as Latin American and Caribbean residents were best positioned to use it.", "cause_zh": "大社会自由派想要更公平、基于技能的制度；允许直系亲属不受配额限制入境的条款产生了深远而意外的后果，拉美和加勒比裔居民最善于利用它。", "sig_en": "Immigration shifted America's orientation from the Atlantic to the Pacific Rim, revived urban and suburban economies, and fueled renewed debates over identity and affirmative action as demographers predicted a 'majority-minority' nation between 2040 and 2050.", "sig_zh": "移民把美国的重心从大西洋转向太平洋沿岸，复兴了城乡经济，也在人口学家预测2040至2050年间出现“多数少数族裔”国家之际激起关于身份和平权行动的新争论。", "exp_en": "The 1965 act was one of the Great Society's least debated but most transformative laws: it remade the nation's demography without anyone planning the result.", "exp_zh": "1965年法案是大社会立法中辩论最少却变革最大的法律之一：它在无人筹划结果的情况下重塑了国家人口结构。", "page": 1013, "src": {"text": "Immigration policy should be generous; it should be fair; it should be flexible.", "attr": "John F. Kennedy, A Nation of Immigrants, 1964"}, "img": {"file": "img:f2_1908", "credit": "图源：Henretta《America's History》第8版 p.1013"}}, {"id": "p9-034", "period": 9, "topic_en": "Multiculturalism and the backlash: Proposition 209", "topic_zh": "多元文化主义与反弹：209号提案", "year": null, "year_text": "1990s", "who": ["Ron Unz"], "who_zh": ["朗·安兹"], "what_en": "In the 1990s multiculturalism replaced the melting pot as the model of diversity, while voters pushed back: California's Proposition 187 (1994) barred illegal immigrants from public services, Proposition 209 ended affirmative action in California universities, and Proposition 227 (1998) banned bilingual education.", "what_zh": "1990年代多元文化主义取代大熔炉成为多样性模式，选民则反弹：加州187号提案（1994）禁止非法移民使用公共服务，209号提案终结加州大学平权行动，227号提案（1998）禁止双语教育。", "cause_en": "Critics charged that multiculturalism fragmented national unity; with three to five million undocumented immigrants after twenty years under the 1965 law, and disputes over language and affirmative action, states took matters into their own hands.", "cause_zh": "批评者指责多元文化主义分裂国家统一；1965年法案实施二十年后无证移民达三五百万，加上语言和平权行动之争，各州自行采取行动。", "sig_en": "Proposition 227 passed with 61 percent, confirming the limits of multiculturalism even in the nation's most diverse state; diversity — not remedial preference — became the constitutionally acceptable basis for affirmative action.", "sig_zh": "227号提案以61%通过，证实即使在全美最多元化的州多元文化主义也有其限度；“多样性”而非补偿性优待成为平权行动合宪的依据。", "exp_en": "The 1990s replayed the early-1900s nativist conflicts with a new vocabulary: the melting pot gave way to multiculturalism, and assimilation gave way to ballots.", "exp_zh": "1990年代用新词汇重演了20世纪初的本土主义冲突：大熔炉让位于多元文化主义，同化让位于选票。", "page": 1015}, {"id": "p9-035", "period": 9, "topic_en": "The 'culture war' of the 1990s", "topic_zh": "1990年代的“文化战争”", "year": 1992, "year_text": "1992 (Buchanan's convention speech)", "who": ["Patrick Buchanan"], "who_zh": ["帕特里克·布坎南"], "what_en": "At the 1992 Republican National Convention, Pat Buchanan declared 'a religious war going on in our country for the soul of America' — 'a culture war' over abortion, gay rights, and the legacy of the 1960s.", "what_zh": "1992年共和党全国代表大会上，帕特·布坎南宣称美国正在打一场“为美国灵魂而战的宗教战争”——围绕堕胎、同性恋权利和1960年代遗产的“文化战争”。", "cause_en": "The struggle between religious traditionalists and secular liberals, dating to the 1920s, reignited in the long shadow of the sixties as conservatives attacked multiculturalism and what they saw as threats to family values.", "cause_zh": "可追溯到1920年代的宗教传统派与世俗自由派之争，在六十年代的漫长阴影下重燃，保守派抨击多元文化主义和他们眼中对家庭价值观的威胁。", "sig_en": "The culture war drove the divisive partisanship of the 1990s — amplified by 24-hour cable news like Fox News and CNN — over abortion, affirmative action, and gay rights.", "sig_zh": "文化战争推动了1990年代的分裂性党争——被福克斯新闻、CNN等24小时有线新闻放大——围绕堕胎、平权行动和同性恋权利展开。", "why_term": "culture war", "why_term_q": "1992年布坎南在共和党大会上宣称美国正在打一场 ______。", "exp_en": "The culture war turned private morality into public politics: bedrooms, classrooms, and clinics became the battlegrounds of national elections.", "exp_zh": "文化战争把私人道德变成公共政治：卧室、教室和诊所成了全国大选的战场。", "page": 1012, "img": {"file": "img:f2_1905", "credit": "图源：Henretta《America's History》第8版 p.1012"}}, {"id": "p9-036", "period": 9, "topic_en": "The abortion battles: Operation Rescue, Webster, and Casey", "topic_zh": "堕胎之战：“拯救行动”、韦伯斯特案与凯西案", "year": 1989, "year_text": "1989 (Webster); 1992 (Casey)", "who": ["Randall Terry"], "who_zh": ["兰德尔·特里"], "what_en": "Fundamentalist Protestants took over the antiabortion movement: Randall Terry founded Operation Rescue in 1987 to blockade clinics, and the Supreme Court in Webster (1989) and Casey (1992) upheld state restrictions while affirming Roe's essential holding.", "what_zh": "基要派新教徒接管反堕胎运动：兰德尔·特里1987年创立“拯救行动”封锁诊所；最高法院在韦伯斯特案（1989）和凯西案（1992）中支持州限制，同时确认罗伊案的核心判决。", "cause_en": "Since Roe v. Wade (1973), prochoice feminists and prolife religious conservatives had defined the issue from opposite perspectives — the woman's control over her body versus the unborn fetus's rights — making abortion the defining issue between Democrats and Republicans.", "cause_zh": "自1973年罗伊诉韦德案起，主张选择的女权主义者和主张生命的宗教保守派就从对立视角定义这一问题——女性对身体的控制权对未出生胎儿的权利——使堕胎成为两党分野的标志性议题。", "sig_en": "A reporter called 1989 'the year the Court turned right,' but Casey showed the Court creeping, not lurching, right: it upheld a 24-hour waiting period while preserving the constitutional right to abortion.", "sig_zh": "有记者称1989年是“最高法院右转之年”，但凯西案显示法院是渐进而非剧烈右转：支持24小时等待期，同时保留堕胎宪法权利。", "exp_en": "Abortion politics show how the Court mediates the culture war: each decision narrowed or preserved rights at the margins without settling the underlying moral conflict.", "exp_zh": "堕胎政治显示最高法院如何调解文化战争：每个判决都在边缘收缩或保留权利，却从未解决根本的道德冲突。", "page": 1019, "img": {"file": "img:f2_1929", "credit": "图源：Henretta《America's History》第8版 p.1019"}}, {"id": "p9-037", "period": 9, "topic_en": "Gay rights: the Defense of Marriage Act and Lawrence v. Texas", "topic_zh": "同性恋权利：《婚姻保护法》与劳伦斯诉得州案", "year": 1998, "year_text": "1998 (Defense of Marriage Act); 2003 (Lawrence v. Texas)", "who": ["Anthony Kennedy"], "who_zh": ["安东尼·肯尼迪"], "what_en": "In 1998 Congress passed the Defense of Marriage Act, letting states refuse to recognize same-sex marriages or civil unions from other jurisdictions; in Lawrence v. Texas (2003) the Court struck down state antisodomy laws, limiting states' power over private homosexual conduct.", "what_zh": "1998年国会通过《婚姻保护法》，允许各州拒绝承认其他州的同性婚姻或民事结合；2003年劳伦斯诉得州案中最高法院推翻州反鸡奸法，限制各州干预成年人私密同性行为的权力。", "cause_en": "As gay Americans came out after Stonewall and won local antidiscrimination protections, the Religious Right condemned homosexuality as morally wrong and voters in states like Colorado (1992) tried to block gay-rights ordinances.", "cause_zh": "石墙事件后越来越多同性恋者公开身份并赢得地方反歧视保护，宗教右翼谴责同性恋在道德上错误，科罗拉多等州选民（1992）试图阻止同性恋权利条例。", "sig_en": "The two moves showed the Court and Congress pulling in opposite directions; the Court later declared the Defense of Marriage Act unconstitutional in Windsor v. United States (2013).", "sig_zh": "这两步显示最高法院与国会朝相反方向拉扯；法院后来在2013年温莎诉美国案中宣布《婚姻保护法》违宪。", "exp_en": "Gay rights moved through all three branches: Congress restricted, states experimented, and the Court — via Reagan appointee Kennedy's Lawrence opinion — constitutionalized privacy.", "exp_zh": "同性恋权利走遍三权：国会设限、各州试验、最高法院——经里根任命的肯尼迪在劳伦斯案中的意见——把隐私权宪法化。", "page": 1020}, {"id": "p9-038", "period": 9, "topic_en": "The election of 1992 and Bill Clinton's 'third way'", "topic_zh": "1992年大选与克林顿的“第三条道路”", "year": 1992, "year_text": "November 1992", "who": ["Bill Clinton", "George H. W. Bush", "H. Ross Perot", "Albert A. Gore", "Hillary Rodham Clinton"], "who_zh": ["比尔·克林顿", "乔治·H·W·布什", "罗斯·佩罗", "阿尔·戈尔", "希拉里·罗德姆·克林顿"], "what_en": "Arkansas governor Bill Clinton, a 'New Democrat,' won with only 43.7 percent of the popular vote as independent Ross Perot took 19 percent; Clinton's 'third way' sought to satisfy both the party's liberal wing and Reagan-era moderates.", "what_zh": "阿肯色州州长、“新民主党人”比尔·克林顿仅以43.7%普选票获胜，独立候选人罗斯·佩罗拿走19%；克林顿的“第三条道路”试图同时满足党内自由派和里根时代温和派。", "cause_en": "A 1991 recession and Bush's broken domestic promises opened the door; Clinton styled himself to win back Reagan Democrats and middle-class voters, choosing fellow southerner Al Gore — the first baby-boom, all-southern ticket — as running mate.", "cause_zh": "1991年衰退和布什国内承诺落空打开了大门；克林顿把自己塑造成能赢回里根民主党人和中产选民的人选，挑选南方同乡阿尔·戈尔作搭档——首张婴儿潮、全南方组合。", "sig_en": "Clinton returned Democrats to the White House after twelve years and balanced the budget by 1998, but his health-care plan — led by First Lady Hillary Clinton — died by mid-1994, triggering the 1994 Republican resurgence.", "sig_zh": "克林顿使民主党在十二年后重返白宫，到1998年平衡了预算，但由第一夫人希拉里主导的医改计划1994年中夭折，触发1994年共和党反扑。", "exp_en": "Clinton's third way was triangulation as governing philosophy: borrow the right's economics, keep the left's social goals, and survive between them.", "exp_zh": "克林顿的第三条道路是作为执政哲学的三角策略：借用右派的经济，保留左派的社会目标，在两者之间求生。", "page": 1020}, {"id": "p9-039", "period": 9, "topic_en": "The Contract with America and the Republican resurgence of 1994", "topic_zh": "《与美国契约》与1994年共和党复兴", "year": 1994, "year_text": "November 1994 (midterms)", "who": ["Newt Gingrich"], "who_zh": ["纽特·金里奇"], "what_en": "Led by Representative Newt Gingrich's 'Contract with America' — tax cuts, welfare reductions, anticrime measures, deregulation — Republicans gained fifty-two House seats in 1994, winning the House for the first time since 1954, plus the Senate and eleven governorships.", "what_zh": "在众议员纽特·金里奇“与美国契约”（减税、削减福利、反犯罪、放松管制）带领下，共和党1994年赢得52个众议院席位，自1954年以来首次掌控众议院，还夺回参议院和十一个州长职位。", "cause_en": "The failure of Clinton's health-care plan and the perception of liberal overreach gave conservatives a working majority; Gingrich revived Reagan Revolution themes that George H. W. Bush had neglected.", "cause_zh": "克林顿医改失败和自由派冒进的观感给了保守派可运作的多数；金里奇重拾老布什忽视的里根革命主题。", "sig_en": "Clinton moved right, declaring in 1996 that 'the era of big government is over,' and signed conservative welfare reform — a triumph of the New Right's long march through the institutions.", "sig_zh": "克林顿向右转，1996年宣称“大政府时代已经结束”，并签署保守派的福利改革——新右翼长征的胜利。", "exp_en": "1994 proved realignments are reversible: two years after a Democratic presidential win, voters handed Congress to the most conservative House majority in forty years.", "exp_zh": "1994年证明重组是可逆的：民主党赢得总统两年后，选民把国会交给了四十年来最保守的众议院多数。", "page": 1021, "img": {"file": "img:f2_1934", "credit": "图源：Henretta《America's History》第8版 p.1021"}}, {"id": "p9-040", "period": 9, "topic_en": "Welfare reform: the Personal Responsibility and Work Opportunity Reconciliation Act", "topic_zh": "福利改革：《个人责任与工作机会协调法》", "year": 1996, "year_text": "August 1996", "who": ["Bill Clinton"], "who_zh": ["比尔·克林顿"], "what_en": "In August 1996 Clinton signed the Personal Responsibility and Work Opportunity Reconciliation Act, abolishing the AFDC program Democrats had created in 1935 and ending the federal guarantee of welfare.", "what_zh": "1996年8月克林顿签署《个人责任与工作机会协调法》，废除民主党1935年创建的AFDC项目，终结联邦福利保障。", "cause_en": "Many taxpayers believed AFDC encouraged recipients to stay on welfare rather than seek employment; Clinton, seeking Republican support for a centrist New Democrat program after the 1994 losses, embraced the long-standing conservative goal.", "cause_zh": "许多纳税人认为AFDC鼓励受助者赖在福利上不工作；1994年惨败后克林顿为争取共和党支持其中间派新民主党纲领，接受了保守派的长期目标。", "sig_en": "The law saved relatively little money but carried a big ideological message: liberals were furious with the president, while conservatives celebrated achieving a goal Reagan himself had never reached.", "sig_zh": "该法省钱不多但意识形态信号强烈：自由派对总统愤怒，保守派则庆祝实现了里根本人都没达到的目标。", "exp_en": "Welfare reform was the clearest proof that the Reagan era had changed the terms of debate: a Democratic president dismantled a New Deal program to prove big government was over.", "exp_zh": "福利改革是里根时代改变辩论规则的最清晰证明：一位民主党总统为证明大政府终结而拆除了一个新政项目。", "page": 1022, "img": {"file": "img:f2_1937", "credit": "图源：Henretta《America's History》第8版 p.1022"}}, {"id": "p9-041", "period": 9, "topic_en": "The impeachment of Bill Clinton", "topic_zh": "克林顿弹劾案", "year": 1998, "year_text": "1998–1999", "who": ["Bill Clinton", "Monica Lewinsky", "Kenneth Starr"], "who_zh": ["比尔·克林顿", "莫妮卡·莱温斯基", "肯尼思·斯塔尔"], "what_en": "After denying an affair with White House intern Monica Lewinsky, Clinton was investigated by independent prosecutor Kenneth Starr; on December 19, 1998 the House approved two articles of impeachment for perjury and obstruction of justice, but the Senate acquitted him in early 1999.", "what_zh": "克林顿否认与白宫实习生莫妮卡·莱温斯基有染后，遭独立检察官肯尼思·斯塔尔调查；1998年12月19日众议院以伪证和妨碍司法通过两项弹劾条款，但参议院1999年初宣告他无罪。", "cause_en": "Conservative Republicans, who never accepted Clinton's legitimacy, favored a much lower standard for 'high crimes and misdemeanors'; Starr concluded that lying about the extramarital affair constituted perjury and obstruction of justice.", "cause_zh": "从不承认克林顿合法性的保守派共和党人主张对“重罪与轻罪”采用低得多的标准；斯塔尔认定关于婚外情的谎言构成伪证和妨碍司法。", "sig_en": "Only 38 percent of Americans favored impeachment while 58 percent opposed it; acquitted like Andrew Johnson before him, Clinton was left politically crippled, unable to fashion a Democratic alternative to the Republican agenda.", "sig_zh": "仅38%美国人支持弹劾、58%反对；如当年的安德鲁·约翰逊一样被判无罪的克林顿政治上陷入瘫痪，无力构建民主党替代共和党的议程。", "exp_en": "The impeachment showed partisanship consuming constitutional process: a private scandal became a national trial because the opposition refused to accept the president's legitimacy.", "exp_zh": "弹劾案显示党争吞噬宪法程序：一桩私德丑闻变成全国审判，因为反对派拒绝承认总统的合法性。", "page": 1022, "img": {"file": "img:f2_1937", "credit": "图源：Henretta《America's History》第8版 p.1022"}}, {"id": "p9-042", "period": 9, "topic_en": "The contested election of 2000 and Bush v. Gore", "topic_zh": "2000年争议大选与布什诉戈尔案", "year": 2000, "year_text": "November–December 2000", "who": ["George W. Bush", "Al Gore", "Ralph Nader", "John Paul Stevens"], "who_zh": ["乔治·W·布什", "阿尔·戈尔", "拉尔夫·纳德", "约翰·保罗·史蒂文斯"], "what_en": "Al Gore won the popular vote (50.9 to 50.4 million) but lost the electoral college 267–271; after a month of Florida recount battles, the Supreme Court in Bush v. Gore ordered the recount stopped, letting Bush's victory stand.", "what_zh": "阿尔·戈尔赢得普选票（5090万对5040万）却以267比271输掉选举人团；佛罗里达重新计票僵持一个月后，最高法院在布什诉戈尔案中下令停止计票，确认布什获胜。", "cause_en": "The razor-thin Florida tally triggered Democratic recount demands; Green candidate Ralph Nader drew away votes that would have carried Gore to victory, and the Court, voting along conservative/liberal lines, ruled that recounting without a uniform standard violated equal protection.", "cause_zh": "佛罗里达极微弱的票差触发民主党要求重新计票；绿党候选人拉尔夫·纳德分走了本可助戈尔获胜的选票；最高法院按保守/自由派别投票，裁定没有统一标准地计票违反平等保护。", "sig_en": "Justice John Paul Stevens warned the partisan decision undermined the nation's confidence in judges as impartial guardians of the rule of law; the Court declared its own ruling not precedent, and Bush entered office a minority president.", "sig_zh": "约翰·保罗·史蒂文斯大法官警告这一党派判决损害了国民对法官作为法治公正守护者的信心；法院声明该判决不作判例，布什以少数派总统身份上任。", "exp_en": "Bush v. Gore put the Court at the center of presidential politics: five justices effectively chose the president, deepening the partisan distrust the culture wars had already inflamed.", "exp_zh": "布什诉戈尔案把最高法院推到总统政治中心：五位大法官实际上选出了总统，加深了文化战争早已点燃的党派互不信任。", "page": 1025, "img": {"file": "img:f2_1944", "credit": "图源：Henretta《America's History》第8版 p.1025"}}, {"id": "p9-043", "period": 9, "topic_en": "The Bush tax cuts: the Economic Growth and Tax Relief Act of 2001", "topic_zh": "布什减税：2001年《经济增长与税收减免协调法》", "year": 2001, "year_text": "2001 (second round 2003)", "who": ["George W. Bush", "Karl Rove"], "who_zh": ["乔治·W·布什", "卡尔·罗夫"], "what_en": "Bush's Economic Growth and Tax Relief Act of 2001 slashed income tax rates, extended the earned income credit for the poor, and marked the estate tax to be phased out by 2010; a second 2003 round cut dividend and capital-gains taxes.", "what_zh": "布什2001年《经济增长与税收减免协调法》大幅削减所得税率、扩大穷人劳动所得税抵免、2010年前逐步取消遗产税；2003年第二轮削减股息和资本利得税。", "cause_en": "Taxes engaged Bush most, as they had Reagan; adviser Karl Rove argued a permanent Republican majority could be built on the party's conservative base, foreclosing the campaign centrism of 'a uniter, not a divider.'", "cause_zh": "减税是布什最关心的国内议题，一如里根；顾问卡尔·罗夫认为可在保守派基础上建立永久共和党多数，终结了竞选时“团结者而非分裂者”的中间路线。", "sig_en": "Bush pushed further than any postwar president, even Reagan, in slashing federal taxes; the cuts skewed benefits upward while the national debt passed $8 trillion midway through his second term.", "sig_zh": "布什在削减联邦税上走得比任何战后总统、甚至里根都远；减税好处向上倾斜，而第二任期中段国债已超8万亿美元。", "exp_en": "The Bush tax cuts replayed Reaganomics with the same result: lower revenues, higher deficits, and gains concentrated at the top.", "exp_zh": "布什减税重演了里根经济学，结果相同：收入下降、赤字上升、收益集中在顶层。", "page": 1026}, {"id": "p9-044", "period": 9, "topic_en": "The Great Recession and the election of Barack Obama", "topic_zh": "大衰退与奥巴马当选", "year": 2008, "year_text": "2007–2008 (recession); November 4, 2008 (election)", "who": ["Barack Obama", "Hillary Rodham Clinton", "John McCain", "Henry Paulson"], "who_zh": ["巴拉克·奥巴马", "希拉里·罗德姆·克林顿", "约翰·麦凯恩", "亨利·保尔森"], "what_en": "The worst downturn since the 1930s — the Dow lost half its value, unemployment hit 10 percent, millions defaulted on mortgages — propelled Democrat Barack Obama, the first African American nominee, to victory over John McCain on November 4, 2008.", "what_zh": "1930年代以来最严重的衰退——道指腰斩、失业率达10%、数百万人房贷违约——把首位非洲裔总统候选人、民主党人巴拉克·奥巴马送上总统宝座，2008年11月4日击败约翰·麦凯恩。", "cause_en": "The 2008 financial collapse, rooted in deregulated, crash-prone global finance, plus two Middle East wars, discredited Republican governance; Treasury Secretary Henry Paulson's $700 billion bank bailout (the Emergency Economic Stabilization Act) could not save the party, and Obama beat Hillary Clinton in a historic primary.", "cause_zh": "源于放松管制、易崩盘的全球金融的2008年崩溃，加上两场中东战争，使共和党执政信誉扫地；财长保尔森7000亿美元银行救助（《紧急经济稳定法》）救不了本党，奥巴马在历史性初选中击败希拉里。", "sig_en": "Obama inherited two wars and the Great Recession; his election marked how far civil rights gains had carried a nation that two generations earlier would not let black Americans dine with whites.", "sig_zh": "奥巴马接手两场战争和大衰退；他的当选标志着民权成果把国家带得多远——两代人前这个国家还不让黑人与白人同桌用餐。", "exp_en": "2008 fused economic crisis with demographic change: a collapsing economy elected a president who embodied the multicultural America the culture wars had contested.", "exp_zh": "2008年把经济危机与人口变迁熔于一炉：崩溃的经济选出了一位本身就体现着文化战争所争夺的多元文化美国的总统。", "page": 1030}, {"id": "p9-045", "period": 9, "topic_en": "Obama's domestic agenda: the stimulus, the Tea Party, and the Affordable Care Act", "topic_zh": "奥巴马国内议程：刺激法案、茶党与平价医疗法案", "year": 2010, "year_text": "2009–2010 (ARRA 2009; ACA signed March 23, 2010)", "who": ["Barack Obama", "Sonia Sotomayor", "Elena Kagan"], "who_zh": ["巴拉克·奥巴马", "索尼娅·索托马约尔", "埃琳娜·卡根"], "what_en": "Congress passed the $787 billion American Recovery and Reinvestment Act (2009) and, despite the far-right Tea Party's opposition, the Patient Protection and Affordable Care Act, signed March 23, 2010 — the first major health reform since Medicare (1965).", "what_zh": "国会通过7870亿美元《美国复兴与再投资法》（2009），并在极右翼茶党反对下通过《患者保护与平价医疗法案》，2010年3月23日签署——这是自1965年医疗保险以来首次重大医改。", "cause_en": "With the economy in free fall, Democrats used their majorities for stimulus and health reform; the Tea Party gave voice to the extreme individualism and antigovernment sentiment traditionally associated with right-wing movements.", "cause_zh": "经济自由落体之际，民主党利用多数地位推动刺激和医改；茶党则以右翼运动传统的极端个人主义和反政府情绪发声。", "sig_en": "The Tea Party rallied Americans against the health-care bill, but it passed; after Democrats lost the House in 2010, Obama turned to executive authority — repealing 'Don't Ask, Don't Tell' in 2011 and appointing Sonia Sotomayor and Elena Kagan to the Supreme Court.", "sig_zh": "茶党动员美国人反对医改法案，但法案仍获通过；2010年民主党失去众议院后，奥巴马转向行政权力——2011年废除“不问不说”政策，并任命索尼娅·索托马约尔和埃琳娜·卡根为大法官。", "exp_en": "Obama's first two years show the cycle of modern reform: ambitious legislation, fierce backlash, then gridlock — with the courts and executive orders carrying what Congress would not.", "exp_zh": "奥巴马上任头两年显示现代改革的循环：雄心勃勃的立法、激烈的反弹、然后僵局——国会不做的事由法院和行政命令来扛。", "page": 1031, "img": {"file": "img:f2_1965", "credit": "图源：Henretta《America's History》第8版 p.1031"}}];